function mean(a){var s=0;for(var i=0;i<a.length;i++)s+=a[i];return s/a.length;}
function rank(a){ var idx=a.map(function(v,i){return [v,i];}).sort(function(p,q){return p[0]-q[0];});
  var r=new Array(a.length); var i=0;
  while(i<a.length){ var j=i; while(j+1<a.length && idx[j+1][0]===idx[i][0]) j++;
    var avg=(i+j)/2+1; for(var k=i;k<=j;k++) r[idx[k][1]]=avg; i=j+1; }
  return r; }
function spearman(x,y){ var rx=rank(x), ry=rank(y), n=x.length;
  var mx=mean(rx), my=mean(ry), num=0, dx=0, dy=0;
  for(var i=0;i<n;i++){ var a=rx[i]-mx, b=ry[i]-my; num+=a*b; dx+=a*a; dy+=b*b; }
  if(dx===0||dy===0) return 0; return num/Math.sqrt(dx*dy); }
var EXPORTS={mean:mean,rank:rank,spearman:spearman};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpearmanForgePure = EXPORTS; }
